function nullableText(value: string) {
  return value.trim() || null;
}

const validationPathLabels: Record<string, string> = {
  template: "Template", pricing: "Pricing", priceMatrices: "Price Matrices", workstationRows: "Workstation Rows", baseModelRows: "Base / Model Rows", modularGroups: "Modular Groups", optionGroups: "Options / Accessories", materialSuggestions: "Material Suggestions", linkedFamilySuggestions: "Linked Family Suggestions", extractionWarnings: "Extraction Warnings", defaultCurrency: "Default Currency", confidence: "Confidence", selection: "Selection Rule",
};

function friendlyValidationPath(path: string) {
  if (path === "draft.confidence") return "Confidence";
  return path.replace(/^draft\.?/, "").split(".").flatMap((part) => {
    const indexed = /^(.*)\[(\d+)\]$/.exec(part);
    if (indexed) return [validationPathLabels[indexed[1]] ?? indexed[1], `Row ${Number(indexed[2]) + 1}`];
    return [validationPathLabels[part] ?? part.replace(/([a-z])([A-Z])/g, "$1 $2")];
  }).join(" → ");
}

function receivedValue(rawJson: string, path: string) {
  try {
    let value: unknown = JSON.parse(rawJson);
    for (const token of path.replace(/^draft\.?/, "").matchAll(/([^.[\]]+)|\[(\d+)\]/g)) {
      value = Array.isArray(value) ? value[Number(token[2])] : value && typeof value === "object" ? (value as Record<string, unknown>)[token[1]] : undefined;
    }
    return value === undefined ? null : JSON.stringify(value);
  } catch { return null; }
}

function ValidationErrorPanel({ rawJson, result }: { rawJson: string; result: Exclude<SmartProductJsonImportResult, { kind: "valid" }> }) {
  if (result.kind === "validation") return <section role="alert" className="mt-3 max-h-48 overflow-y-auto rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-950"><p className="font-semibold">Validation failed — {result.validation.errors.length} {result.validation.errors.length === 1 ? "issue" : "issues"}</p><ul className="mt-2 space-y-3">{result.validation.errors.map((issue: ProductTemplateDraftIssue, index) => { const received = receivedValue(rawJson, issue.path); const confidence = issue.path === "draft.confidence"; return <li key={`${issue.path}-${index}`}><p className="font-medium">{friendlyValidationPath(issue.path)}</p><p>{issue.message}{received !== null ? ` Received: ${received}.` : ""}</p>{confidence ? <p>Example: use 0.95 for 95% confidence.</p> : null}</li>; })}</ul></section>;
  return <section role="alert" className="mt-3 rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-950"><p className="font-semibold">JSON syntax error</p><p className="mt-1">{result.message}</p></section>;
}

function section({ title, children }: { title: string; children: ReactNode }) {
  return <section className="rounded-lg border border-zinc-200 bg-white p-4"><details className="group"><summary className="flex cursor-pointer list-none items-center justify-between gap-3"><h3 className="text-sm font-semibold text-zinc-900">{title}</h3><span className="text-xs font-semibold text-emerald-900 group-open:hidden">Show</span><span className="hidden text-xs font-semibold text-emerald-900 group-open:inline">Hide</span></summary><div className="mt-3">{children}</div></details></section>;
}

function TextField({ label, multiline, onChange, value }: { label: string; multiline?: boolean; onChange: (value: string) => void; value: string | null }) {
  return <label className="block"><span className="mb-1 block text-xs font-medium text-zinc-600">{label}</span>{multiline
    ? <textarea value={value ?? ""} onChange={(event) => onChange(event.target.value)} className={textareaClass} />
    : <input value={value ?? ""} onChange={(event) => onChange(event.target.value)} className={inputClass} />}</label>;
}

function CurrencyField({ onChange, value }: { onChange: (value: ProductTemplateDraftCurrency | null) => void; value: ProductTemplateDraftCurrency | null }) {
  return <select value={value ?? ""} onChange={(event) => onChange((event.target.value || null) as ProductTemplateDraftCurrency | null)} className={inputClass}><option value="">None</option>{currencies.map((currency) => <option key={currency} value={currency}>{currency}</option>)}</select>;
}

function PriceField({ label, onChange, value }: { label: string; onChange: (value: number | null) => void; value: number | null }) {
  return <label className="block"><span className="mb-1 block text-xs font-medium text-zinc-600">{label}</span><input type="number" step="any" value={value ?? ""} onChange={(event) => onChange(nullableReviewNumber(event.target.value))} className={inputClass} /></label>;
}

