const destinationLabels: Record<SmartReviewDestination, string> = {
  base_model: "Base / Model Pricing", workstation: "Workstation Pricing", category_matrix: "Category / Matrix Pricing",
  modular: "Modular Pricing", accessory: "Accessory / Configuration", skip: "Skip / Do Not Apply",
};
const roleLabels: Record<SmartReviewAccessoryConfiguration["role"], string> = { accessory: "Normal Accessory", conditional_option: "Conditional Option", companion: "Required Companion" };
const selectionLabels: Record<SmartReviewAccessoryConfiguration["selection"], string> = { optional_multiple: "Optional / Multiple", optional_exactly_one: "Optional / Exactly One", required_exactly_one: "Required / Exactly One", required_at_least_one: "Required / At Least One", multiple: "Multiple" };

function AdditionalJsonDialog({ currentDraft, currentPlan, onAdd, onClose }: { currentDraft: ProductTemplateDraft; currentPlan: SmartSetupReviewRoutingPlan; onAdd: (draft: ProductTemplateDraft, plan: SmartSetupReviewRoutingPlan) => void; onClose: () => void }) {
  const [rawJson, setRawJson] = useState("");
  const [result, setResult] = useState<SmartProductJsonImportResult | null>(null);
  const [decisions, setDecisions] = useState<Record<string, SmartAdditionalGroupDecision>>({});
  const incomingDraft = result?.kind === "valid" ? result.validation.draft : null;
  const groups = incomingDraft ? smartAdditionalJsonGroups(currentDraft, currentPlan, incomingDraft) : [];
  const validate = () => {
    const next = parseSmartProductJsonImport(rawJson); setResult(next);
    if (next.kind !== "valid" || !next.validation.draft) return;
    const incomingGroups = smartAdditionalJsonGroups(currentDraft, currentPlan, next.validation.draft);
    setDecisions(Object.fromEntries(incomingGroups.map(({ route, compatibleTargets }) => [route.key, { action: (["workstation", "base_model"].includes(route.sourceKind) && compatibleTargets.length ? "skip" : "add"), destination: route.recommendedDestination, targetKey: null, duplicateChoices: {} } satisfies SmartAdditionalGroupDecision])));
  };
  const updateDecision = (key: string, patch: Partial<SmartAdditionalGroupDecision>) => setDecisions((current) => ({ ...current, [key]: { ...current[key], ...patch } }));
  const commit = () => {
    if (!incomingDraft) return;
    const validationWarnings = result?.kind === "valid" ? result.validation.warnings.map((warning) => warning.message) : [];
    const enrichedIncoming = { ...incomingDraft, extractionWarnings: [...new Set([...incomingDraft.extractionWarnings, ...validationWarnings])] };
    const merged = applySmartAdditionalJson(currentDraft, currentPlan, enrichedIncoming, decisions); onAdd(merged.draft, merged.plan);
  };
  return <div role="dialog" aria-modal="true" aria-label="Add More JSON" className="fixed inset-0 z-[70] flex items-center justify-center bg-zinc-950/50 p-4"><div className="flex max-h-[88vh] w-full max-w-4xl flex-col overflow-hidden rounded-xl bg-white shadow-xl"><div className="flex items-center justify-between border-b border-zinc-200 p-4"><div><h3 className="font-semibold">Add More JSON</h3><p className="text-xs text-zinc-500">The current reviewed workspace remains unchanged until you confirm.</p></div><button type="button" onClick={onClose} className="text-sm font-medium">Close</button></div><div className="min-h-0 flex-1 overflow-y-auto p-4">{!incomingDraft ? <><textarea value={rawJson} onChange={(event) => { setRawJson(event.target.value); setResult(null); }} aria-label="Additional AI JSON" className="min-h-64 w-full rounded-md border border-zinc-300 p-3 font-mono text-xs" />{result && result.kind !== "valid" ? <ValidationErrorPanel rawJson={rawJson} result={result} /> : null}<button type="button" onClick={validate} className="mt-3 rounded-md bg-emerald-900 px-3 py-2 text-sm font-semibold text-white">Validate JSON</button></> : <><div className="rounded-md border border-emerald-200 bg-emerald-50 p-3 text-sm"><p className="font-semibold">Validated ProductTemplateDraft v1</p><p className="mt-1 text-xs">{groups.length} logical groups · {incomingDraft.materialSuggestions.length} materials · {incomingDraft.sources.length} sources</p></div>{groups.length ? <div className="mt-3 space-y-3">{groups.map(({ route, compatibleTargets }) => { const decision = decisions[route.key]; const target = compatibleTargets.find((item) => item.key === decision?.targetKey); const duplicates = target ? smartAdditionalDuplicateRows(currentDraft, incomingDraft, route, target) : []; const flatAlreadyExists = ["workstation", "base_model"].includes(route.sourceKind) && compatibleTargets.length > 0; return <section key={route.key} className="rounded-md border border-zinc-200 p-3"><div className="flex flex-wrap justify-between gap-2"><div><p className="font-semibold">{route.sourceName}</p><p className="text-xs text-zinc-500">{route.sourceKind.replace("_", " / ")} · {route.rowCount} rows/items{route.columnCount !== null ? ` · ${route.columnCount} columns` : ""}</p></div><p className="text-xs text-emerald-800">Recommended: {destinationLabels[route.recommendedDestination]}</p></div>{compatibleTargets.length ? <p className="mt-1 text-xs text-zinc-500">Possible match: {compatibleTargets.map((item) => item.groupName).join(", ")}</p> : null}<div className="mt-3 grid gap-2 sm:grid-cols-3"><label className="text-xs">Action<select className={`${inputClass} mt-1`} value={decision?.action ?? "skip"} onChange={(event) => updateDecision(route.key, { action: event.target.value as SmartAdditionalGroupDecision["action"], targetKey: null, duplicateChoices: {} })}><option value="add" disabled={flatAlreadyExists}>Add as New Group</option><option value="merge" disabled={!compatibleTargets.length}>Merge Into Existing Group</option><option value="skip">Skip</option></select></label>{decision?.action === "add" ? <label className="text-xs sm:col-span-2">Apply As<select className={`${inputClass} mt-1`} value={decision.destination} onChange={(event) => updateDecision(route.key, { destination: event.target.value as SmartReviewDestination })}>{SMART_REVIEW_DESTINATIONS.map((destination) => <option key={destination} value={destination} disabled={!route.supportedDestinations.includes(destination)}>{destinationLabels[destination]}</option>)}</select></label> : null}{decision?.action === "merge" ? <label className="text-xs sm:col-span-2">Existing group<select className={`${inputClass} mt-1`} value={decision.targetKey ?? ""} onChange={(event) => updateDecision(route.key, { targetKey: event.target.value || null, duplicateChoices: {} })}><option value="">Choose target…</option>{compatibleTargets.map((item) => <option key={item.key} value={item.key}>{item.groupName}</option>)}</select></label> : null}</div>{duplicates.length ? <div className="mt-3 space-y-2 rounded border border-amber-200 bg-amber-50 p-2"><p className="text-xs font-semibold text-amber-950">{duplicates.length} potential duplicate/conflict{duplicates.length === 1 ? "" : "s"}</p>{duplicates.map(({ key, existing, incoming, fields }) => <div key={key} className="flex flex-wrap items-center justify-between gap-2 border-t border-amber-100 pt-2 text-xs"><div><p className="font-medium">{smartSubgroupRowLabel(incoming)}</p>{fields.length ? <p className="text-amber-900">Changed: {fields.join(", ")}</p> : null}<p className="text-amber-900">Existing: {"price" in existing ? String(existing.price) : JSON.stringify(existing.prices)} · Incoming: {"price" in incoming ? String(incoming.price) : JSON.stringify(incoming.prices)}</p></div><select value={decision.duplicateChoices[key] ?? "existing"} onChange={(event) => updateDecision(route.key, { duplicateChoices: { ...decision.duplicateChoices, [key]: event.target.value as "existing" | "incoming" } })} className="h-8 rounded border border-amber-300 bg-white px-2"><option value="existing">Keep Existing</option><option value="incoming">Use Incoming</option></select></div>)}</div> : null}</section>; })}</div> : <p className="mt-3 text-sm text-zinc-600">No pricing/accessory groups were found. Supplemental materials, sources, and warnings can still be added.</p>}</>}</div>{incomingDraft ? <div className="flex justify-end gap-2 border-t border-zinc-200 p-4"><button type="button" onClick={() => { setResult(null); setDecisions({}); }} className="rounded-md border border-zinc-300 px-3 py-2 text-sm font-semibold">Back to JSON</button><button type="button" onClick={commit} disabled={groups.some(({ route }) => decisions[route.key]?.action === "merge" && !decisions[route.key]?.targetKey)} className="rounded-md bg-emerald-900 px-3 py-2 text-sm font-semibold text-white disabled:opacity-50">Add Selected Data</button></div> : null}</div></div>;
}

function routeItems(draft: ProductTemplateDraft, route: SmartReviewRoute) {
  if (route.sourceKind === "option") return draft.optionGroups.find((group) => group.id === route.sourceId)?.items ?? [];
  if (route.sourceKind === "matrix") return draft.pricing.priceMatrices.find((matrix) => matrix.id === route.sourceId)?.rows ?? [];
  if (route.sourceKind === "base_model") return draft.pricing.baseModelRows;
  if (route.sourceKind === "workstation") return draft.pricing.workstationRows;
  if (route.sourceKind === "modular") return draft.pricing.modularGroups.find((group) => group.id === route.sourceId)?.matrix.rows ?? [];
  return [];
}

function baseModelChoices(draft: ProductTemplateDraft, plan: SmartSetupReviewRoutingPlan) {
  const flat = plan.routes.find((route) => route.key === "base_model:rows");
  const flatChoices = flat?.destination === "base_model" ? draft.pricing.baseModelRows.map((row) => ({ groupId: LEGACY_BASE_MODEL_GROUP_ID, row, groupName: flat.groupName })) : [];
  const matrixChoices = draft.pricing.priceMatrices.flatMap((matrix) => {
    const route = plan.routes.find((item) => item.key === `matrix:${matrix.id}`);
    return route?.destination === "base_model" ? matrix.rows.map((row) => ({ groupId: matrix.id, row, groupName: route.groupName })) : [];
  });
  return [...flatChoices, ...matrixChoices];
}

function SmartSubgroupEditor({ draft, images, onChange, onImageChange, route, subgroups }: { draft: ProductTemplateDraft; images: ReviewImages; onChange: (subgroups: SmartReviewedPricingSubgroups[string]) => void; onImageChange: ReviewImageChange; route: SmartReviewRoute; subgroups: SmartReviewedPricingSubgroups[string] }) {
  const rows = routeItems(draft, route); const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});
  const assigned = new Map(subgroups.flatMap((subgroup) => subgroup.row_ids.map((rowId) => [rowId, subgroup.id] as const)));
  return <div className="mt-3 rounded-md border border-emerald-100 bg-emerald-50/40 p-3"><div className="flex items-center justify-between gap-2"><div><p className="text-xs font-semibold text-emerald-950">Visual subgroups</p><p className="text-[10px] text-emerald-800">Optional. Rows remain pricing-authoritative.</p></div><button type="button" onClick={() => { const id = crypto.randomUUID(); onChange([...subgroups, { id, subgroup_name: "New Subgroup", sort_order: subgroups.length, is_active: true, row_ids: [] }]); }} className="rounded-md border border-emerald-200 bg-white px-2 py-1 text-xs font-semibold text-emerald-900">+ Add Subgroup</button></div>
    <div className="mt-3 space-y-2">{subgroups.map((subgroup) => <div key={subgroup.id} className="rounded-md border border-zinc-200 bg-white p-2"><div className="flex flex-wrap items-start gap-2"><button type="button" onClick={() => setCollapsed((current) => ({ ...current, [subgroup.id]: !current[subgroup.id] }))} className="h-7 w-7 rounded border border-zinc-200 text-xs">{collapsed[subgroup.id] ? ">" : "v"}</button><StagedPricingRowReferenceImage sourceKey={`subgroup:${route.key}`} rowId={subgroup.id} image={images[reviewedSubgroupImageKey(route.key, subgroup.id)] ?? null} onChange={(image) => onImageChange(`subgroup:${route.key}`, subgroup.id, image)} /><div className="min-w-48 flex-1"><input value={subgroup.subgroup_name} onChange={(event) => onChange(subgroups.map((entry) => entry.id === subgroup.id ? { ...entry, subgroup_name: event.target.value } : entry))} className={inputClass} /><p className="mt-1 text-[10px] text-zinc-500">{subgroup.row_ids.length} models</p></div><button type="button" onClick={() => onChange(subgroups.filter((entry) => entry.id !== subgroup.id))} className="text-xs font-semibold text-red-700">Remove</button></div>{!collapsed[subgroup.id] ? <div className="mt-2 space-y-1 border-t border-zinc-100 pt-2">{rows.filter((row) => assigned.get(row.id) === subgroup.id).map((row) => <p key={row.id} className="text-xs text-zinc-700">{smartSubgroupRowLabel(row)}</p>)}{!subgroup.row_ids.length ? <p className="text-xs text-zinc-400">No rows assigned.</p> : null}</div> : null}</div>)}</div>
    {subgroups.length ? <div className="mt-3 space-y-2 border-t border-emerald-100 pt-3"><p className="text-[10px] font-semibold uppercase text-zinc-500">Row assignment</p>{rows.map((row) => <label key={row.id} className="grid gap-1 text-xs sm:grid-cols-[1fr_180px] sm:items-center"><span>{smartSubgroupRowLabel(row)}</span><select value={assigned.get(row.id) ?? ""} onChange={(event) => { const nextId = event.target.value || null; onChange(subgroups.map((subgroup) => ({ ...subgroup, row_ids: subgroup.id === nextId ? [...subgroup.row_ids.filter((id) => id !== row.id), row.id] : subgroup.row_ids.filter((id) => id !== row.id) }))); }} className="h-8 rounded border border-zinc-300 bg-white px-2"><option value="">Ungrouped</option>{subgroups.map((subgroup) => <option key={subgroup.id} value={subgroup.id}>{subgroup.subgroup_name}</option>)}</select></label>)}</div> : null}
  </div>;
}

function SmartRoutingReview({ draft, images, onChange, onImageChange, onSubgroupsChange, plan, subgroups }: { draft: ProductTemplateDraft; images: ReviewImages; onChange: (plan: SmartSetupReviewRoutingPlan) => void; onImageChange: ReviewImageChange; onSubgroupsChange: (subgroups: SmartReviewedPricingSubgroups) => void; plan: SmartSetupReviewRoutingPlan; subgroups: SmartReviewedPricingSubgroups }) {
  const models = baseModelChoices(draft, plan);
  const validation = validateSmartSetupReviewRouting(draft, plan);
  const updateRoute = (key: string, update: (route: SmartReviewRoute) => SmartReviewRoute) => onChange({ routes: plan.routes.map((route) => route.key === key ? update(route) : route) });
  const moveRoute = (key: string, direction: "up" | "down") => onChange(reorderSmartSetupReviewRoutes(plan, key, direction));
  const summary = smartSetupRoutingSummary(plan).filter((item) => item.count > 0).map((item) => `${item.count} ${destinationLabels[item.destination]}`).join(" · ");
  return <section className="rounded-lg border border-emerald-200 bg-emerald-50/50 p-4"><details className="group"><summary className="flex cursor-pointer list-none items-center justify-between gap-3"><div><h3 className="text-sm font-semibold text-emerald-950">Review destinations</h3><p className="mt-1 text-xs text-emerald-900">{summary} · {validation.valid ? "Ready" : `${validation.errors.length} issues`}</p></div><span className="text-xs font-semibold text-emerald-900 group-open:hidden">Show</span><span className="hidden text-xs font-semibold text-emerald-900 group-open:inline">Hide</span></summary><div className="mt-3"><p className="text-xs text-emerald-900">Recommendations are suggestions. Apply uses your selections below.</p>
    <div className="mt-4 grid gap-3 xl:grid-cols-2">{plan.routes.map((route, routeIndex) => {
      const items = routeItems(draft, route);
      const accessory = route.accessory;
      const conditional = accessory && accessory.role !== "accessory";
      const subgroupCount = (subgroups[route.key] ?? []).length;
      const issueCount = validation.errors.filter((error) => error.includes(route.sourceName)).length;
      return <article key={route.key} className="rounded-lg border border-zinc-200 bg-white p-4"><details className="group"><summary className="flex cursor-pointer list-none flex-wrap items-start justify-between gap-2"><div><p className="font-semibold text-zinc-900">{route.sourceName}</p><p className={`text-xs ${issueCount ? "font-semibold text-red-700" : "text-zinc-500"}`}>{destinationLabels[route.destination]} · {route.rowCount} {route.sourceKind === "option" ? "items" : "models"}{subgroupCount ? ` · ${subgroupCount} subgroup${subgroupCount === 1 ? "" : "s"}` : ""} · {issueCount ? `${issueCount} issue${issueCount === 1 ? "" : "s"}` : accessory && accessory.role !== "accessory" ? roleLabels[accessory.role] : "Ready"}</p></div><span className="flex items-center gap-1"><button type="button" disabled={routeIndex === 0} onClick={(event) => { event.preventDefault(); moveRoute(route.key, "up"); }} className="rounded border border-zinc-200 px-1.5 py-0.5 text-xs disabled:opacity-40" aria-label={`Move ${route.sourceName} up`}>↑</button><button type="button" disabled={routeIndex === plan.routes.length - 1} onClick={(event) => { event.preventDefault(); moveRoute(route.key, "down"); }} className="rounded border border-zinc-200 px-1.5 py-0.5 text-xs disabled:opacity-40" aria-label={`Move ${route.sourceName} down`}>↓</button><span className="text-xs font-semibold text-emerald-900 group-open:hidden">Show</span><span className="hidden text-xs font-semibold text-emerald-900 group-open:inline">Hide</span></span></summary>
        <div className="flex flex-wrap items-start justify-between gap-2"><div><p className="font-semibold text-zinc-900">{route.sourceName}</p><p className="text-xs text-zinc-500">{route.sourceKind.replace("_", " / ")} · {route.rowCount} rows/items{route.columnCount !== null ? ` · ${route.columnCount} price columns` : ""}</p></div><p className="text-xs font-medium text-emerald-800">Recommended: {destinationLabels[route.recommendedDestination]}</p></div>
        <div className="mt-3 grid gap-3 sm:grid-cols-2"><label><span className="mb-1 block text-xs font-medium text-zinc-600">Apply As</span><select className={inputClass} value={route.destination} onChange={(event) => updateRoute(route.key, (current) => { const destination = event.target.value as SmartReviewDestination; return { ...current, destination, ...(destination === "accessory" && !current.accessory ? { accessory: { role: "accessory", selection: "optional_multiple", rules: [] } } : {}) }; })}>{SMART_REVIEW_DESTINATIONS.map((destination) => <option key={destination} value={destination} disabled={!route.supportedDestinations.includes(destination)}>{destinationLabels[destination]}</option>)}</select></label><TextField label="Destination group name" value={route.groupName} onChange={(groupName) => updateRoute(route.key, (current) => ({ ...current, groupName }))} /></div>
        {route.destination !== "skip" && items.length ? <SmartSubgroupEditor draft={draft} images={images} onImageChange={onImageChange} route={route} subgroups={subgroups[route.key] ?? []} onChange={(next) => onSubgroupsChange({ ...subgroups, [route.key]: next })} /> : null}
        {route.destination === "accessory" && accessory ? <div className="mt-3 space-y-3 border-t border-zinc-100 pt-3"><div className="grid gap-3 sm:grid-cols-2"><label><span className="mb-1 block text-xs font-medium text-zinc-600">Configuration Type</span><select className={inputClass} value={accessory.role} onChange={(event) => updateRoute(route.key, (current) => ({ ...current, accessory: { ...current.accessory!, role: event.target.value as SmartReviewAccessoryConfiguration["role"] } }))}>{Object.entries(roleLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label><span className="mb-1 block text-xs font-medium text-zinc-600">Selection Rule</span><select className={inputClass} value={accessory.selection} onChange={(event) => updateRoute(route.key, (current) => ({ ...current, accessory: { ...current.accessory!, selection: event.target.value as SmartReviewAccessoryConfiguration["selection"] } }))}>{Object.entries(selectionLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label></div>
          {conditional ? <div><p className="text-xs font-semibold text-zinc-700">Applicable Models</p>{models.length ? <div className="mt-2 space-y-2">{models.map(({ groupId, row, groupName }) => { const ruleIndex = accessory.rules.findIndex((rule) => rule.baseModelGroupId === groupId && rule.baseModelRowId === row.id); const rule = accessory.rules[ruleIndex]; const selected = Boolean(rule); const label = `${groupName} · ${[...row.supplierCodes, ...row.referenceCodes][0] ?? "No supplier code"} — ${row.displayName ?? row.label ?? row.id}${row.dimensions ? ` · ${formatDraftDimensions(row.dimensions)}` : ""}`; return <div key={`${groupId}:${row.id}`} className="rounded-md border border-zinc-200 p-2"><label className="flex items-start gap-2 text-xs"><input type="checkbox" checked={selected} onChange={(event) => updateRoute(route.key, (current) => { const rules = current.accessory!.rules; return { ...current, accessory: { ...current.accessory!, rules: event.target.checked ? [...rules, { baseModelGroupId: groupId, baseModelRowId: row.id, required: smartReviewSelectionContract(current.accessory!.selection).required, ...(current.accessory!.selection === "required_exactly_one" ? { fixedQuantity: 1 } : {}) }] : rules.filter((_, index) => index !== ruleIndex) } }; })} /><span>{label}</span></label>{rule ? <div className="mt-2 grid gap-2 pl-5 sm:grid-cols-3"><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={rule.required} onChange={(event) => updateRoute(route.key, (current) => ({ ...current, accessory: { ...current.accessory!, rules: current.accessory!.rules.map((item, index) => index === ruleIndex ? { ...item, required: event.target.checked } : item) } }))} />Required</label><label className="text-xs">Allowed Items<select className="mt-1 h-8 w-full rounded border border-zinc-300" value={rule.allowedItemIds ? "specific" : "all"} onChange={(event) => updateRoute(route.key, (current) => ({ ...current, accessory: { ...current.accessory!, rules: current.accessory!.rules.map((item, index) => index === ruleIndex ? { ...item, allowedItemIds: event.target.value === "specific" ? [] : undefined } : item) } }))}><option value="all">All Items</option><option value="specific">Specific Items</option></select></label><label className="text-xs">Fixed Quantity<input className="mt-1 h-8 w-full rounded border border-zinc-300 px-2" type="number" min="1" step="1" value={rule.fixedQuantity ?? ""} onChange={(event) => updateRoute(route.key, (current) => ({ ...current, accessory: { ...current.accessory!, rules: current.accessory!.rules.map((item, index) => index === ruleIndex ? { ...item, fixedQuantity: event.target.value === "" ? undefined : Number(event.target.value) } : item) } }))} /></label>{rule.allowedItemIds ? <div className="sm:col-span-3 flex flex-wrap gap-3">{items.map((item) => <label key={item.id} className="flex items-center gap-1 text-xs"><input type="checkbox" checked={rule.allowedItemIds!.includes(item.id)} onChange={(event) => updateRoute(route.key, (current) => ({ ...current, accessory: { ...current.accessory!, rules: current.accessory!.rules.map((entry, index) => index === ruleIndex ? { ...entry, allowedItemIds: event.target.checked ? [...(entry.allowedItemIds ?? []), item.id] : (entry.allowedItemIds ?? []).filter((id) => id !== item.id) } : entry) } }))} />{item.displayName ?? item.label ?? item.id}</label>)}</div> : null}</div> : null}</div>; })}</div> : <p className="mt-1 text-xs text-amber-800">Route at least one reviewed group to Base / Model Pricing to author applicability rules.</p>}</div> : null}
        </div> : null}
      </details></article>;
    })}</div></div>
  </details></section>;
}

function SmartProductReview({ draft, images, onChange, onImageChange, validationWarnings }: { draft: ProductTemplateDraft; images: ReviewImages; onChange: (draft: ProductTemplateDraft) => void; onImageChange: ReviewImageChange; validationWarnings: string[] }) {
  const warningSummary = smartProductWarningSummary(draft, validationWarnings);
  const detectedSections = getSmartProductReviewSections(draft);
  return <div className="space-y-4"><section className="rounded-lg border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-950"><p className="font-semibold">EDITABLE SMART SETUP REVIEW</p><div className="mt-2 flex flex-wrap items-baseline gap-x-5 gap-y-1"><p className="text-base font-semibold">{draft.template.templateName || "Unnamed product"}</p><p>{warningSummary.count} extraction warnings</p></div>{detectedSections.length ? <ul className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs">{detectedSections.map(([label, count]) => <li key={label}>• {count} {label}</li>)}</ul> : null}{warningSummary.count ? <details className="mt-3 rounded-md border border-amber-200 bg-amber-50 p-2"><summary className="cursor-pointer font-semibold text-amber-900">Review warnings</summary><ul className="mt-2 space-y-1 text-xs text-amber-950">{warningSummary.warnings.map((warning, index) => <li key={`${warning}-${index}`}>⚠ {warning}</li>)}</ul></details> : null}</section>
    {section({ title: "Template Details", children: <div className="grid gap-3 md:grid-cols-2"><TextField label="Template name" value={draft.template.templateName} onChange={(value) => onChange(updateReviewedTemplate(draft, { templateName: nullableText(value) }))} /><TextField label="Template code" value={draft.template.templateCode} onChange={(value) => onChange(updateReviewedTemplate(draft, { templateCode: nullableText(value) }))} /><TextField label="Item code" value={draft.template.itemCode} onChange={(value) => onChange(updateReviewedTemplate(draft, { itemCode: nullableText(value) }))} /><TextField label="Internal selection name" value={draft.template.internalSelectionName} onChange={(value) => onChange(updateReviewedTemplate(draft, { internalSelectionName: nullableText(value) }))} /><TextField label="Origin" value={draft.template.origin} onChange={(value) => onChange(updateReviewedTemplate(draft, { origin: nullableText(value) }))} /><TextField label="Supplier name" value={draft.template.supplierName} onChange={(value) => onChange(updateReviewedTemplate(draft, { supplierName: nullableText(value) }))} /><label><span className="mb-1 block text-xs font-medium text-zinc-600">Default currency</span><CurrencyField value={draft.defaultCurrency} onChange={(defaultCurrency) => onChange(updateReviewedTemplate(draft, { defaultCurrency }))} /></label><div className="md:col-span-2"><TextField multiline label="Description" value={draft.template.description} onChange={(value) => onChange(updateReviewedTemplate(draft, { description: nullableText(value) }))} /></div><div className="md:col-span-2"><TextField multiline label="Master specification" value={draft.template.specification} onChange={(value) => onChange(updateReviewedTemplate(draft, { specification: nullableText(value) }))} /></div></div> })}
    {draft.pricing.workstationRows.length ? section({ title: "Workstation Pricing", children: <PricedRowsEditor workstation imageScope="workstation:rows" images={images} onImageChange={onImageChange} rows={draft.pricing.workstationRows} onChange={(rows) => onChange({ ...draft, pricing: { ...draft.pricing, workstationRows: rows as ProductTemplateDraftWorkstationRow[] } })} /> }) : null}
    {draft.pricing.baseModelRows.length ? section({ title: "Base / Model Pricing", children: <PricedRowsEditor imageScope="base_model:rows" images={images} onImageChange={onImageChange} rows={draft.pricing.baseModelRows} onChange={(rows) => onChange({ ...draft, pricing: { ...draft.pricing, baseModelRows: rows } })} /> }) : null}
    {draft.pricing.priceMatrices.length ? section({ title: "Category / Matrix Pricing", children: <div className="space-y-5">{draft.pricing.priceMatrices.map((matrix, matrixIndex) => <MatrixEditor key={matrix.id} imageScope={`matrix:${matrix.id}`} images={images} onImageChange={onImageChange} matrix={matrix} onChange={(nextMatrix) => onChange(updateReviewedMatrix(draft, matrixIndex, nextMatrix))} />)}</div> }) : null}
    {draft.pricing.modularGroups.length ? section({ title: "Modular Item Pricing", children: <div className="space-y-4">{draft.pricing.modularGroups.map((group, groupIndex) => <div key={group.id} className="rounded-md border border-zinc-200 p-3"><div className="grid gap-3 md:grid-cols-2"><TextField label="Modular group label" value={group.label} onChange={(value) => onChange({ ...draft, pricing: { ...draft.pricing, modularGroups: draft.pricing.modularGroups.map((item, index) => index === groupIndex ? { ...item, label: nullableText(value) } : item) } })} /><TextField label="Default specification" value={group.defaultSpecification} onChange={(value) => onChange({ ...draft, pricing: { ...draft.pricing, modularGroups: draft.pricing.modularGroups.map((item, index) => index === groupIndex ? { ...item, defaultSpecification: nullableText(value) } : item) } })} /></div><div className="mt-3"><MatrixEditor imageScope={`modular:${group.id}`} images={images} onImageChange={onImageChange} matrix={group.matrix} onChange={(matrix) => onChange({ ...draft, pricing: { ...draft.pricing, modularGroups: draft.pricing.modularGroups.map((item, index) => index === groupIndex ? { ...item, matrix } : item) } })} /></div></div>)}</div> }) : null}
    {draft.optionGroups.length ? section({ title: "Options / Accessories", children: <div className="space-y-4">{draft.optionGroups.map((group, groupIndex) => <div key={group.id} className="rounded-md border border-zinc-200 p-3"><TextField label="Option group label" value={group.label} onChange={(value) => onChange({ ...draft, optionGroups: draft.optionGroups.map((item, index) => index === groupIndex ? { ...item, label: nullableText(value) } : item) })} /><p className="mt-1 text-xs text-zinc-500">Extracted selection rule: {formatSelectionRule(group.selection)}</p><div className="mt-3"><PricedRowsEditor imageScope={`option:${group.id}`} images={images} onImageChange={onImageChange} rows={group.items} onChange={(items) => onChange({ ...draft, optionGroups: draft.optionGroups.map((item, index) => index === groupIndex ? { ...item, items } : item) })} /></div></div>)}</div> }) : null}
    {draft.materialSuggestions.length ? section({ title: "Material Suggestions", children: <div className="space-y-3">{draft.materialSuggestions.map((item, index) => <div key={item.id} className="grid gap-3 rounded-md border border-zinc-200 p-3 md:grid-cols-2"><TextField label="Material label" value={item.label} onChange={(value) => onChange({ ...draft, materialSuggestions: draft.materialSuggestions.map((entry, entryIndex) => entryIndex === index ? { ...entry, label: nullableText(value) } : entry) })} /><TextField multiline label="Notes" value={item.notes} onChange={(value) => onChange({ ...draft, materialSuggestions: draft.materialSuggestions.map((entry, entryIndex) => entryIndex === index ? { ...entry, notes: nullableText(value) } : entry) })} /></div>)}</div> }) : null}
    {draft.linkedFamilySuggestions.length ? section({ title: "Linked Family Suggestions", children: <div className="space-y-3">{draft.linkedFamilySuggestions.map((item, index) => <div key={item.id} className="grid gap-3 rounded-md border border-zinc-200 p-3 md:grid-cols-2"><TextField label="Template name" value={item.templateName} onChange={(value) => onChange({ ...draft, linkedFamilySuggestions: draft.linkedFamilySuggestions.map((entry, entryIndex) => entryIndex === index ? { ...entry, templateName: nullableText(value) } : entry) })} /><TextField label="Template code" value={item.templateCode} onChange={(value) => onChange({ ...draft, linkedFamilySuggestions: draft.linkedFamilySuggestions.map((entry, entryIndex) => entryIndex === index ? { ...entry, templateCode: nullableText(value) } : entry) })} /><PriceField label="Default quantity" value={item.defaultQuantity} onChange={(defaultQuantity) => onChange({ ...draft, linkedFamilySuggestions: draft.linkedFamilySuggestions.map((entry, entryIndex) => entryIndex === index ? { ...entry, defaultQuantity } : entry) })} /><TextField multiline label="Notes" value={item.notes} onChange={(value) => onChange({ ...draft, linkedFamilySuggestions: draft.linkedFamilySuggestions.map((entry, entryIndex) => entryIndex === index ? { ...entry, notes: nullableText(value) } : entry) })} /></div>)}</div> }) : null}
  </div>;
}

export function SmartProductJsonImport({ buttonLabel = "✦ Import from AI JSON", loadInitialWorkspace, onApplyManufacturerFields, onApplyManufacturerPrices, onRequestApply }: { buttonLabel?: string; loadInitialWorkspace?: () => ManufacturerUpdateWorkspace | null; onApplyManufacturerFields?: (patches: ManufacturerFieldPatch[], actions: ManufacturerItemAction[]) => { ok: true } | { ok: false; message: string }; onApplyManufacturerPrices?: (patches: ManufacturerPriceDifference[]) => { ok: true } | { ok: false; message: string }; onRequestApply?: (draft: ProductTemplateDraft, routingPlan: SmartSetupReviewRoutingPlan, confirmed?: boolean, pendingImages?: PendingProductTemplateRowImage[], subgroupAssignments?: SmartAppliedPricingSubgroups[], pendingSubgroupImages?: PendingProductTemplateSubgroupImage[]) => true | SmartSetupPricingSection[] }) {
  const [open, setOpen] = useState(false);
  const [rawJson, setRawJson] = useState("");
  const [result, setResult] = useState<SmartProductJsonImportResult | null>(null);
  const [reviewedDraft, setReviewedDraft] = useState<ProductTemplateDraft | null>(null);
  const [routingPlan, setRoutingPlan] = useState<SmartSetupReviewRoutingPlan | null>(null);
  const [reviewIsDirty, setReviewIsDirty] = useState(false);
  const [conflicts, setConflicts] = useState<SmartSetupPricingSection[]>([]);
  const [reviewedSubgroups, setReviewedSubgroups] = useState<SmartReviewedPricingSubgroups>({});
  const [stagedImages, setStagedImages] = useState<ReviewImages>({});
  const [addMoreOpen, setAddMoreOpen] = useState(false);
  const [importCount, setImportCount] = useState(0);
  const [scopeWorkspace, setScopeWorkspace] = useState<ManufacturerUpdateWorkspace | null>(null);
  const [scopeOpen, setScopeOpen] = useState(false);
  const [pricesOnlyOpen, setPricesOnlyOpen] = useState(false);
  const [selectedSectionsOpen, setSelectedSectionsOpen] = useState(false);
  const stagedImagesRef = useRef<ReviewImages>({});
  const revokeImages = (images: ReviewImages) => disposeStagedReviewedRowImages(images, URL.revokeObjectURL);
  const clearReview = () => { setOpen(false); setRawJson(""); setResult(null); setReviewedDraft(null); setRoutingPlan(null); setReviewIsDirty(false); setConflicts([]); setReviewedSubgroups({}); setAddMoreOpen(false); setImportCount(0); };
  const close = () => { if (reviewedDraft && !window.confirm("Discard the current reviewed and merged workspace? Staged images and subgroup assignments will also be discarded.")) return; revokeImages(stagedImagesRef.current); stagedImagesRef.current = {}; setStagedImages({}); clearReview(); };
  useEffect(() => () => revokeImages(stagedImagesRef.current), []);
  const transferAndClearImages = (pendingImages: Array<{ previewUrl: string }>) => {
    const transferred = new Set(pendingImages.map((image) => image.previewUrl));
    Object.values(stagedImagesRef.current).forEach((image) => { if (!transferred.has(image.previewUrl)) URL.revokeObjectURL(image.previewUrl); });
    stagedImagesRef.current = {}; setStagedImages({}); clearReview();
  };
  const changeStagedImage: ReviewImageChange = (sourceKey, rowId, image) => {
    setStagedImages((current) => {
      const next = updateStagedReviewedRowImage(current, sourceKey, rowId, image, URL.revokeObjectURL);
      stagedImagesRef.current = next;
      return next;
    });
    setReviewIsDirty(true); setConflicts([]);
  };
  const validate = () => {
    const nextResult = parseSmartProductJsonImport(rawJson);
    setResult(nextResult);
    const nextDraft = nextResult.kind === "valid" && nextResult.validation.draft ? createReviewedProductTemplateDraft(nextResult.validation.draft) : null;
    setReviewedDraft(nextDraft);
    setRoutingPlan(nextDraft ? createSmartSetupReviewRouting(nextDraft) : null);
    setReviewedSubgroups({});
    setReviewIsDirty(false);
    setConflicts([]);
    setImportCount(nextDraft ? 1 : 0);
  };
  const requestApply = () => {
    if (!reviewedDraft || !routingPlan || !validateSmartSetupReviewRouting(reviewedDraft, routingPlan).valid) return;
    const pendingImages = pendingRowImagesForSmartSetupApply(reviewedDraft, routingPlan, stagedImagesRef.current);
    const subgroupAssignments = canonicalSubgroupsForSmartSetupApply(reviewedDraft, routingPlan, reviewedSubgroups);
    const pendingSubgroupImages = pendingSubgroupImagesForSmartSetupApply(reviewedDraft, routingPlan, reviewedSubgroups, stagedImagesRef.current);
    const response = onRequestApply?.(reviewedProductTemplateDraftForApply(reviewedDraft), routingPlan, false, pendingImages, subgroupAssignments, pendingSubgroupImages) ?? true;
    if (Array.isArray(response)) setConflicts(response);
    else transferAndClearImages(onRequestApply ? [...pendingImages, ...pendingSubgroupImages] : []);
  };
  const confirmApply = () => { const pendingImages = reviewedDraft && routingPlan ? pendingRowImagesForSmartSetupApply(reviewedDraft, routingPlan, stagedImagesRef.current) : []; const subgroupAssignments = reviewedDraft && routingPlan ? canonicalSubgroupsForSmartSetupApply(reviewedDraft, routingPlan, reviewedSubgroups) : []; const pendingSubgroupImages = reviewedDraft && routingPlan ? pendingSubgroupImagesForSmartSetupApply(reviewedDraft, routingPlan, reviewedSubgroups, stagedImagesRef.current) : []; if (reviewedDraft && routingPlan) onRequestApply?.(reviewedProductTemplateDraftForApply(reviewedDraft), routingPlan, true, pendingImages, subgroupAssignments, pendingSubgroupImages); transferAndClearImages(onRequestApply ? [...pendingImages, ...pendingSubgroupImages] : []); };
  const labels = getSmartSetupConflictLabels(conflicts);
  const validationWarnings = result?.kind === "valid" ? result.validation.warnings.map((warning) => warning.message) : [];
  const routingValidation = reviewedDraft && routingPlan ? validateSmartSetupReviewRouting(reviewedDraft, routingPlan) : { valid: false, errors: [] };
  const summary = routingPlan ? smartSetupRoutingSummary(routingPlan).filter((item) => item.count > 0) : [];

  const startGeneralImport = (workspace = loadInitialWorkspace?.()) => { if (workspace) { setReviewedDraft(workspace.draft); setRoutingPlan(workspace.plan); setReviewedSubgroups(workspace.subgroups ?? {}); setImportCount(1); setReviewIsDirty(false); setOpen(true); setAddMoreOpen(true); return; } setOpen(true); };
  const openImporter = () => { if (loadInitialWorkspace && onApplyManufacturerPrices) { const workspace = loadInitialWorkspace(); if (workspace) { setScopeWorkspace(workspace); setScopeOpen(true); return; } } startGeneralImport(); };
  if (scopeOpen && scopeWorkspace) return <><button type="button" onClick={openImporter} className="rounded-md border border-emerald-200 bg-white px-3 py-2 text-xs font-semibold text-emerald-900">{buttonLabel}</button><div role="dialog" aria-modal="true" aria-label="Choose AI JSON update scope" className="fixed inset-0 z-[75] flex items-center justify-center bg-zinc-950/50 p-4"><div className="w-full max-w-md rounded-xl bg-white p-5 shadow-xl"><div className="flex items-start justify-between gap-3"><div><h2 className="text-lg font-semibold">Add / Update from AI JSON</h2><p className="mt-1 text-sm text-zinc-600">Choose how the incoming ProductTemplateDraft should be reviewed.</p></div><button type="button" onClick={() => { setScopeOpen(false); setScopeWorkspace(null); }} className="text-sm font-semibold text-zinc-700">Cancel</button></div><div className="mt-4 grid gap-3"><button type="button" onClick={() => { setScopeOpen(false); startGeneralImport(scopeWorkspace); setScopeWorkspace(null); }} className="rounded-lg border border-zinc-200 p-4 text-left"><span className="block text-sm font-semibold">Import / Add Data</span><span className="mt-1 block text-xs text-zinc-500">Use Add, Merge, Skip, routing, and full editable review.</span></button><button type="button" onClick={() => { setScopeOpen(false); setPricesOnlyOpen(true); }} className="rounded-lg border border-emerald-200 bg-emerald-50 p-4 text-left"><span className="block text-sm font-semibold text-emerald-950">Prices Only</span><span className="mt-1 block text-xs text-emerald-800">Compare and apply selected numeric price fields while locking all other data.</span></button>{onApplyManufacturerFields ? <button type="button" onClick={() => { setScopeOpen(false); setSelectedSectionsOpen(true); }} className="rounded-lg border border-sky-200 bg-sky-50 p-4 text-left"><span className="block text-sm font-semibold text-sky-950">Selected Sections</span><span className="mt-1 block text-xs text-sky-800">Review and explicitly accept individual fields in selected sections.</span></button> : null}</div></div></div></>;
  if (pricesOnlyOpen && scopeWorkspace && onApplyManufacturerPrices) return <><button type="button" onClick={openImporter} className="rounded-md border border-emerald-200 bg-white px-3 py-2 text-xs font-semibold text-emerald-900">{buttonLabel}</button><ManufacturerPriceUpdateDialog current={scopeWorkspace} onApply={onApplyManufacturerPrices} onClose={() => { setPricesOnlyOpen(false); setScopeWorkspace(null); }} /></>;
  if (selectedSectionsOpen && scopeWorkspace && onApplyManufacturerFields) return <><button type="button" onClick={openImporter} className="rounded-md border border-emerald-200 bg-white px-3 py-2 text-xs font-semibold text-emerald-900">{buttonLabel}</button><ManufacturerSelectedSectionsDialog current={scopeWorkspace} onApply={onApplyManufacturerFields} onClose={() => { setSelectedSectionsOpen(false); setScopeWorkspace(null); }} /></>;
  return <><button type="button" onClick={openImporter} className="rounded-md border border-emerald-200 bg-white px-3 py-2 text-xs font-semibold text-emerald-900">{buttonLabel}</button>{open ? <div role="dialog" aria-modal="true" aria-label="Smart Product Setup" className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto bg-zinc-950/40 p-3 sm:p-4"><div className="flex max-h-[92vh] w-[95vw] max-w-none flex-col overflow-hidden rounded-xl bg-zinc-50 shadow-xl"><div className="flex shrink-0 items-center justify-between gap-3 border-b border-zinc-200 bg-white p-5"><div><h2 className="text-lg font-semibold">Smart Product Setup</h2>{reviewedDraft ? <p className="text-xs text-zinc-500">Imported JSON sources: {importCount}</p> : null}</div><div className="flex items-center gap-2">{reviewedDraft && routingPlan ? <button type="button" onClick={() => setAddMoreOpen(true)} className="rounded-md border border-emerald-200 px-3 py-2 text-xs font-semibold text-emerald-900">+ Add More JSON</button> : null}<button type="button" onClick={close} className="text-sm font-medium text-zinc-700">Close</button></div></div>{reviewedDraft && routingPlan ? <div className="min-h-0 flex-1 space-y-4 overflow-y-auto p-4 sm:p-5"><SmartRoutingReview draft={reviewedDraft} images={stagedImages} onImageChange={changeStagedImage} plan={routingPlan} subgroups={reviewedSubgroups} onSubgroupsChange={(next) => { setReviewedSubgroups(next); setReviewIsDirty(true); setConflicts([]); }} onChange={(plan) => { setRoutingPlan(plan); setReviewIsDirty(true); setConflicts([]); }} /><SmartProductReview draft={reviewedDraft} images={stagedImages} onImageChange={changeStagedImage} onChange={(draft) => { setReviewedDraft(draft); setReviewIsDirty(true); setConflicts([]); }} validationWarnings={validationWarnings} /></div> : <div className="min-h-0 flex-1 overflow-y-auto p-5"><textarea value={rawJson} onChange={(event) => { setRawJson(event.target.value); setResult(null); setReviewedDraft(null); setRoutingPlan(null); setReviewIsDirty(false); }} className="min-h-72 w-full rounded-md border border-zinc-300 bg-white p-3 font-mono text-xs" aria-label="AI JSON" />{result && result.kind !== "valid" ? <ValidationErrorPanel rawJson={rawJson} result={result} /> : null}<button type="button" onClick={validate} className="mt-3 rounded-md bg-emerald-900 px-3 py-2 text-sm font-semibold text-white">Validate JSON</button></div>}{reviewedDraft && routingPlan ? <div className="shrink-0 border-t border-zinc-200 bg-white p-4 sm:p-5">{conflicts.length ? <div className="rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm"><p className="font-semibold">Replace existing pricing data?</p><p className="mt-1">The reviewed draft contains data for sections that already contain existing/unsaved values:</p><ul className="mt-2 list-disc pl-5">{labels.map((label) => <li key={label}>{label}</li>)}</ul><p className="mt-2">Nothing will be saved until you manually select Save Template.</p><div className="mt-3 flex justify-end gap-2"><button type="button" onClick={() => setConflicts([])} className="rounded-md border border-zinc-300 px-3 py-2 text-sm font-semibold">Cancel</button><button type="button" onClick={confirmApply} className="rounded-md bg-emerald-900 px-3 py-2 text-sm font-semibold text-white">Continue</button></div></div> : <div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-semibold text-zinc-700">Apply summary</p><p className="mt-1 text-xs text-zinc-600">{summary.map((item) => `${item.count} → ${destinationLabels[item.destination]}`).join(" · ")}</p>{routingValidation.errors.length ? <ul className="mt-1 text-xs text-red-700">{routingValidation.errors.map((error) => <li key={error}>{error}</li>)}</ul> : null}</div><div className="flex gap-2"><button type="button" onClick={() => { if ((reviewIsDirty || importCount > 1) && !window.confirm("Discard the current reviewed and merged workspace? Staged images and subgroup assignments will also be discarded.")) return; revokeImages(stagedImagesRef.current); stagedImagesRef.current = {}; setStagedImages({}); setReviewedSubgroups({}); setReviewedDraft(null); setRoutingPlan(null); setReviewIsDirty(false); setResult(null); }} className="rounded-md border border-zinc-300 px-3 py-2 text-sm font-semibold">Back to JSON</button><button type="button" disabled={!routingValidation.valid} onClick={requestApply} className="rounded-md bg-emerald-900 px-3 py-2 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50">Apply to Product Template</button></div></div>}</div> : null}</div></div> : null}{addMoreOpen && reviewedDraft && routingPlan ? <AdditionalJsonDialog currentDraft={reviewedDraft} currentPlan={routingPlan} onClose={() => setAddMoreOpen(false)} onAdd={(draft, plan) => { setReviewedDraft(draft); setRoutingPlan(plan); setImportCount((count) => count + 1); setReviewIsDirty(true); setConflicts([]); setAddMoreOpen(false); }} /> : null}</>;
}
